import pandas as pd
import matplotlib.pyplot as plt

def task_func(data):
    if not isinstance(data, pd.DataFrame):
        raise ValueError("Input data must be a pandas DataFrame.")

    job_col = None
    for col in data.columns:
        if str(col).lower() == "job":
            job_col = col
            break

    if job_col is None:
        raise ValueError("Input DataFrame must contain a 'job' column.")

    job_counts = data[job_col].dropna().value_counts()

    fig, ax = plt.subplots()
    if job_counts.empty:
        ax.text(0.5, 0.5, "No job data available", ha="center", va="center")
        ax.set_axis_off()
    else:
        ax.pie(job_counts, labels=job_counts.index, autopct="%1.1f%%", startangle=90)
        ax.axis("equal")

    ax.set_title("Job Distribution")
    return fig
